<script setup lang="ts">definePageMeta({layout:false});const form=reactive({login:'',password:''});const error=ref('');const needsOtp=ref(false);const code=ref('');async function submit(){error.value='';try{const r=await $fetch<{requiresTwoFactor?:boolean}>('/api/auth/login',{method:'POST',body:form});if(r.requiresTwoFactor){needsOtp.value=true;return}await navigateTo('/admin')}catch(e){error.value=(e as {data?:{message?:string}}).data?.message||'登录失败'}}async function verify(){error.value='';try{await $fetch('/api/auth/verify-otp',{method:'POST',body:{code:code.value}});await navigateTo('/admin')}catch(e){error.value=(e as {data?:{message?:string}}).data?.message||'验证失败'}}</script>
<template><main class="min-h-screen grid place-items-center p-5"><form class="w-full max-w-sm" @submit.prevent="needsOtp?verify():submit()"><h1 class="text-3xl font-semibold">{{needsOtp?'双重验证':'欢迎回来'}}</h1><p class="mt-2" style="color:var(--muted)">{{needsOtp?'输入验证器代码或恢复码':'登录内容工作台'}}</p><div v-if="!needsOtp" class="mt-8 grid gap-4"><input v-model="form.login" required placeholder="用户名或 Email" class="rounded-lg border bg-transparent p-3"><input v-model="form.password" required type="password" placeholder="密码" class="rounded-lg border bg-transparent p-3"></div><input v-else v-model="code" required autofocus autocomplete="one-time-code" placeholder="6 位代码或恢复码" class="mt-8 w-full rounded-lg border bg-transparent p-3"><p v-if="error" class="mt-4 text-red-600">{{error}}</p><button class="mt-6 w-full rounded-lg py-3 text-white" style="background:var(--accent)">{{needsOtp?'验证并登录':'登录'}}</button><NuxtLink to="/" class="mt-5 block text-center text-sm">返回网站</NuxtLink></form></main></template>
